from typing import Annotated, Literal, Any, Union
from typing_extensions import Tag, Discriminator
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()
@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert_body():
    # This should be recognized as a body parameter. 
    # If it's incorrectly recognized as a query parameter, 
    # FastAPI will return 422 Unprocessable Entity because 
    # the body is empty or the query params are missing.
    response = client.post(
        "/dessert",
        json={"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5}
    )
    print(f"Status code: {response.status_code}")
    print(f"Response: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_dessert_body()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

